import sys, itertools
from functools import lru_cache
sys.setrecursionlimit(100000)

TOP = ('T',)
def C(m,p,t): return ('C',m,p,t)
lin='lin'; un='un'
empty='e'; inp='i'; out='o'; io='io'
hid='hid'; ill='ill'; vis='vis'

# ---------- type relations ----------
def tsub(s,t):
    if s==t: return True
    if s[0]=='C' and t[0]=='C':
        m,q,pl = s[1],s[2],s[3]
        if m==t[1] and pl==t[3]:
            if q==empty: return True              # Ts_empty
            if q==inp and t[2]==io: return True   # Ts_inp
            if q==out and t[2]==io: return True   # Ts_out
    return False

def pol_plus(p,q,r):
    return (p==empty and r==q) or (q==empty and r==p) or (p==inp and q==out and r==io) or (p==out and q==inp and r==io)

def pol_cup(p,q):
    if p==empty: return q
    if p==io: return io
    if q==io: return io
    if p==out and q==inp: return io
    if p==out: return out
    if p==inp and q==out: return io
    if p==inp: return inp
    return q

def tplus(a,b,r):
    if a==TOP and b==TOP and r==TOP: return True
    if a[0]=='C' and b[0]=='C' and r[0]=='C' and a[1]==lin and b[1]==lin and r[1]==lin and a[3]==b[3]==r[3]:
        return pol_plus(a[2],b[2],r[2])
    if a[0]=='C' and b[0]=='C' and r[0]=='C' and a[1]==un and b[1]==un and r[1]==un and a[3]==b[3]==r[3]:
        return r[2]==pol_cup(a[2],b[2])
    return False

def is_unrestricted(t): return t[0]=='C' and t[1]==un

def trem(t,s,r):  # whole t, part s, rest r
    return tsub(s,t) and tplus(s,r,t) and ((not is_unrestricted(t)) or r==t)

def flag_plus(f,g,h):
    return (f==hid and g==ill and h==hid) or (f==ill and g==hid and h==hid) or (f==vis and g==vis and h==vis) or (f==ill and g==ill and h==ill)

# ---------- envs ----------
def dom(g): return [e[0] for e in g]
def rem(n,g):  # remove first occurrence and keep tail
    for i,e in enumerate(g):
        if e[0]==n: return g[i+1:]
    return g
def lookup(n,g):
    for e in g:
        if e[0]==n: return (e[1],e[2])
    return None
def nodup(g): return len(set(dom(g)))==len(g)
def in_entry(n,f,t,g): return (n,f,t) in g

# ---------- split ----------
from functools import lru_cache
@lru_cache(maxsize=None)
def split(g1,g2,g3):
    if not g1 and not g2 and not g3: return True
    if not g1 or not g2: return False
    # choose an entry n from g1 that also occurs in g2
    for i,e1 in enumerate(g1):
        n,f1,t1 = e1
        l2 = lookup(n,g2)
        if l2 is None: continue
        f2,t2 = l2
        # determine combined
        combos=[]
        if t1==TOP and t2==TOP:
            for f in (hid,ill,vis):
                if flag_plus(f1,f2,f): combos.append((f,TOP))
        elif t1[0]=='C' and t2[0]=='C' and t1[1]==lin and t2[1]==lin and t1[3]==t2[3]:
            for pr in (empty,inp,out,io):
                if pol_plus(t1[2],t2[2],pr):
                    for f in (hid,ill,vis):
                        if flag_plus(f1,f2,f): combos.append((f,C(lin,pr,t1[3])))
        elif t1[0]=='C' and t2[0]=='C' and t1[1]==un and t2[1]==un and t1==t2:
            for f in (hid,ill,vis):
                if flag_plus(f1,f2,f): combos.append((f,t1))
        for (f3,t3) in combos:
            if in_entry(n,f3,t3,g3):
                if split(rem(n,g1),rem(n,g2),rem(n,g3)): return True
    return False

# ---------- cons ----------
from functools import lru_cache
@lru_cache(maxsize=None)
def cons(g):
    if not g: return True
    for i,(n,f,t) in enumerate(g):
        ok = (t==TOP) or (t[0]=='C' and t[1]==un) or (t[0]=='C' and t[1]==lin and t[2]==empty)
        if ok and cons(rem(n,g)): return True
    return False

# ---------- processes ----------
# Zero | Par p q | Nu n p | Inp u x p | Out u v p | Bang u x p
def mkzero(): return ('Z',)
def par(a,b): return ('P',a,b)
def nu(n,p): return ('N',n,p)
def inp(u,x,p): return ('I',u,x,p)
def out(u,v,p): return ('O',u,v,p)
def bang(u,x,p): return ('B',u,x,p)

def size(p):
    if p[0]=='Z': return 1
    if p[0]=='P': return size(p[1])+size(p[2])+1
    return size(p[3] if p[0]!='O' else p[3])+1

def secLabs(p):
    if p[0]=='Z': return []
    if p[0]=='P': return secLabs(p[2])+secLabs(p[1])
    if p[0]=='N': return secLabs(p[2])+[p[1]]
    return secLabs(p[3])
def maxl(l):
    m=0
    for (a,b) in l:
        if b>m: m=b
    return m
def ok_pos(p):
    return all(snd2>0 for (a1,snd2) in secLabs(p))

# pmap
def mv(py,pz,pv):
    (y1,y2)=py; (z1,z2)=pz; (v1,v2)=pv
    return pv if (y1==z1 and y2==z2) else py
def pmap(p,z1,z2,v1,v2):
    if p[0]=='Z': return p
    if p[0] in ('B','I'):
        u,x,q = p[1],p[2],p[3]
        r = mv(u,(z1,z2),(v1,v2))
        return (p[0], r, x, pmap(q,z1,z2,v1,v2))
    if p[0]=='O':
        u,v,q = p[1],p[2],p[3]
        r1=mv(u,(z1,z2),(v1,v2)); r2=mv(v,(z1,z2),(v1,v2))
        return ('O',r1,r2,pmap(q,z1,z2,v1,v2))
    if p[0]=='P': return ('P',pmap(p[1],z1,z2,v1,v2),pmap(p[2],z1,z2,v1,v2))
    if p[0]=='N':
        n,q=p[1],p[2]; return ('N',n,pmap(q,z1,z2,v1,v2))

# dep_relabel (with NoDup s)
def dep_relabel(p,s,mx):
    if p[0]=='Z': return p
    if p[0] in ('B','I','O'):
        if p[0]=='O': return ('O',p[1],p[2],dep_relabel(p[3],s,mx))
        return (p[0],p[1],p[2],dep_relabel(p[3],s,mx))
    if p[0]=='P': return ('P',dep_relabel(p[1],s,mx),dep_relabel(p[2],s,mx))
    if p[0]=='N':
        n,q=p[1],p[2]; (h,i)=n; n2=(h,i+mx)
        body = pmap(dep_relabel(q,s,mx),h,i,h,i+mx)
        return ('N',n2,body)

def newEntries(g,l,mx):
    res=[]
    for n in l:
        a1,a2=n
        if lookup(n,g) is not None: continue
        ft = lookup((a1,a2-mx),g)
        if ft is None: f,t = (ill,TOP)
        else: f,t = ft
        res.append((n,f,t))
        res += newEntries(g,[],mx)  # no-op
    return res

def vis_proj(g): return [e for e in g if e[1]==vis]
def ill_proj(g): return [e for e in g if e[1]==ill]
def hid_proj(g): return [e for e in g if e[1]==hid]
