# ---------- type universe ----------
POLS=(empty,inp,out,io)
MODES=(lin,un)
def types_depth(d):
    if d<=0: return [TOP]
    res=[TOP]
    for m in MODES:
        for p in POLS:
            for t in types_depth(d-1):
                res.append(C(m,p,t))
    return res
U1=types_depth(1)
U2=types_depth(2)

def uniq(seq):
    seen=set(); out=[]
    for x in seq:
        if x not in seen: seen.add(x); out.append(x)
    return out

# ---------- typeCheck ----------
TCMEMO={}
def tc(g,p):
    g=tuple(g)
    key=(g,p)
    if key in TCMEMO: return TCMEMO[key]
    TCMEMO[key]=False  # avoid loops (no loops expected)
    r=tc_(g,p)
    TCMEMO[key]=r
    return r

def half_pairs(f,t):
    """given whole entry (f,t), yield ((f1,t1),(f2,t2)) with flag_plus f1 f2 f and tplus t1 t2 t (or un rule)"""
    out=[]
    if t==TOP:
        for f1 in (hid,ill,vis):
            for f2 in (hid,ill,vis):
                if flag_plus(f1,f2,f): out.append(((f1,TOP),(f2,TOP)))
    elif t[0]=='C' and t[1]==un:
        for f1 in (hid,ill,vis):
            for f2 in (hid,ill,vis):
                if flag_plus(f1,f2,f): out.append(((f1,t),(f2,t)))
    elif t[0]=='C' and t[1]==lin:
        pol=t[2]; pl=t[3]
        for p1 in POLS:
            for p2 in POLS:
                if pol_plus(p1,p2,pol):
                    for f1 in (hid,ill,vis):
                        for f2 in (hid,ill,vis):
                            if flag_plus(f1,f2,f): out.append(((f1,C(lin,p1,pl)),(f2,C(lin,p2,pl))))
    return out

def perms(l):
    return list(itertools.permutations(l))

def tc_(g,p):
    k=p[0]
    if k=='Z': return cons(g)
    if k=='N':
        n=p[1]; body=p[2]
        l=lookup(n,g)
        if l is None or l[0]!=hid: return False
        t=l[1]
        return tc([(n,vis,t)]+rem(n,g), body)
    if k=='P':
        p1,p2=p[1],p[2]
        names=dom(g)
        # each name: excluded or included with a choice of half pair
        choices=[]
        for idx,n in enumerate(names):
            f,t=g[idx]
            opts=[None]
            for (h1,h2) in half_pairs(f,t):
                opts.append((h1,h2))
            choices.append((n,opts))
        # enumerate cartesian product
        for combo in itertools.product(*[o for (_,o) in choices]):
            inc=[]; ex=[]
            for (n,opts),ch in zip(choices,combo):
                idx=names.index(n); f,t=g[idx]
                if ch is None: ex.append((n,f,t))
                else: inc.append((n,ch[0],ch[1]))
            if not inc:
                # g1=g2=[] ; split([],[],g) requires g=[]
                if g!=(): continue
                if tc([],p1) and tc([],p2): return True
                continue
            for ord1 in set(itertools.permutations(range(len(inc)))):
                g1=[(inc[i][0],inc[i][1][0],inc[i][1][1]) for i in ord1]
                for ord2 in set(itertools.permutations(range(len(inc)))):
                    g2=[(inc[i][0],inc[i][2][0],inc[i][2][1]) for i in ord2]
                    if split(tuple(g1),tuple(g2),g):
                        if tc(g1,p1) and tc(g2,p2): return True
        return False
    if k=='I':
