# ---------- LTS ----------
def aIn(u,v): return ('aIn',u,v)
def aOut(u,v): return ('aOut',u,v)
def aTau(u): return ('aTau',u)

def act_names(a):
    if a[0]=='aTau': return []
    return [a[1],a[2]]

def notHidden(b,a):
    if a[0]=='aTau': return True
    return b!=a[1] and b!=a[2]

LTS_BUDGET=[0]
def lts_gen(g,p,depth=6):
    g=tuple(g)
    if depth<=0: return
    k=p[0]
    if k=='Z': return
    if k=='P':
        p1,p2=p[1],p[2]
        for (a,g2,q) in lts_gen(g,p1,depth-1):
            yield (a,g2,par(q,p2))
        for (a,g2,q) in lts_gen(g,p2,depth-1):
            yield (a,g2,par(p1,q))
        # communication rules
        # lcomL / lclsL / ucomL / uclsL: p1 output side, p2 input side
        for (a,g2,q) in lts_gen(g,p2,depth-1):  # dummy to touch generator? no
            pass
        yield from comm_gen(g,p1,p2,depth, left=True)
        yield from comm_gen(g,p2,p1,depth, left=False)
        return
    if k=='O':
        u,v,body=p[1],p[2],p[3]
        lu=lookup(u,g); lv=lookup(v,g)
        if lu is not None and lu[0]==vis and lv is not None and lv[0]==vis:
            # lOut
            if lu[1][0]=='C' and lu[1][1]==lin and lu[1][2]==out:
                t=lu[1][3]; t1=lv[1]
                for t2 in U1:
                    if trem(t1,t,t2):
                        gnew=[(u,vis,C(lin,empty,t)),(v,vis,t2)]+rem(u,rem(v,g))
                        yield (aOut(u,v), tuple(gnew), body)
            # uOut
            if lu[1][0]=='C' and lu[1][1]==un and lu[1][2] in (out,io):
                t=lu[1][3]; t1=lv[1]
                for t2 in U1:
                    if trem(t1,t,t2):
                        gnew=[(v,vis,t2)]+rem(v,g)
                        yield (aOut(u,v), tuple(gnew), body)
        return
    if k=='I':
        u,x,body=p[1],p[2],p[3]
        lu=lookup(u,g)
        if lu is None or lu[0]!=vis: return
        for v in dom(g):
            if v==u: continue
            lv=lookup(v,g)
            if lv is None or lv[0]==hid: continue
            f,t1=lv
            # lIn
            if lu[1][0]=='C' and lu[1][1]==lin and lu[1][2]==inp:
                t=lu[1][3]
                for t2 in U1:
                    if tplus(t1,t,t2):
                        gnew=[(u,vis,C(lin,empty,t)),(v,vis,t2)]+rem(u,rem(v,g))
                        yield (aIn(u,v), tuple(gnew), pmap(body,x[0],x[1],v[0],v[1]))
            # uIn
            if lu[1][0]=='C' and lu[1][1]==un and lu[1][2] in (inp,io):
                t=lu[1][3]
                for t2 in U1:
                    if tplus(t1,t,t2):
                        gnew=[(v,vis,t2)]+rem(v,g)
                        yield (aIn(u,v), tuple(gnew), pmap(body,x[0],x[1],v[0],v[1]))
        return
    if k=='B':
        u,x,body=p[1],p[2],p[3]
        lu=lookup(u,g)
        if lu is None or lu[0]!=vis: return
        if not nodup(g): return
        for v in dom(g):
            if v==u: continue
            lv=lookup(v,g)
            if lv is None or lv[0]==hid: continue
            f,t1=lv
            if lu[1][0]=='C' and lu[1][1]==un and lu[1][2] in (inp,io):
                t=lu[1][3]
                for t2 in U1:
                    if tplus(t1,t,t2):
                        mx=maxl(dom(g))
                        q=dep_relabel(body,dom(g),mx)
                        ne=newEntries(g,secLabs(q),mx)
                        gnew=ne+[(v,vis,t2)]+rem(v,g)
                        pnew=par(pmap(body,x[0],x[1],v[0],v[1]), bang(u,x,q))
                        yield (aIn(u,v), tuple(gnew), pnew)
        return
    if k=='N':
        b,body=p[1],p[2]
        # open
        l=lookup(b,g)
        if l is not None and l[0]==hid:
            t=l[1]; inner=[(b,vis,t)]+rem(b,g)
            for (a,g2,q) in lts_gen(inner,body,depth-1):
                if a[0]=='aOut' and a[2]==b:
                    yield (a,g2,q)
        # hide
        for pos in range(len(g)):
            (n,f,t)=g[pos]
            if n==b and f==hid:
                h1=list(g[:pos]); h2=list(g[pos+1:])
                inner=h1+[(b,vis,t)]+h2
                for (a,g2,q) in lts_gen(inner,body,depth-1):
