                        (n2,f2,t2)=g2[pos2]
                        if n2==b and f2==vis:
                            h1p=list(g2[:pos2]); h2p=list(g2[pos2+1:])
                            gnew=h1p+[(b,hid,t2)]+h2p
                            yield (a,tuple(gnew),nu(b,q))
        return

def comm_gen(g,p1,p2,depth,left):
    """p1 = output side, p2 = input side; left=True means dPar p1 p2 (lcomL etc.)"""
    g=tuple(g)
